export async function gate({ referenceDir, submissionDir }) {
  const fs = await import("node:fs");
  const path = await import("node:path");
  const { spawn } = await import("node:child_process");
  const crypto = await import("node:crypto");

  const submissionFile = path.join(submissionDir, "answer.mjs");
  const id = crypto.randomBytes(16).toString("hex");
  const runnerFile = path.join(referenceDir, ".r-" + id + ".mjs");
  const nonce = crypto.randomBytes(32).toString("hex");

  function oracle(arr) {
    const out = [];
    for (let i = 0; i < arr.length; i++) {
      if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);
    }
    return out;
  }

  function makeRng(seed) {
    let s = seed >>> 0;
    return function () {
      s = (s + 0x6D2B79F5) >>> 0;
      let t = s;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  const tests = [];
  const add = (a) => { tests.push(a); };

  add([]);
  add([0]);
  add([0, 0]);
  add([0, 0, 0]);
  add([0, 0, 0, 0]);
  add([1]);
  add([-1]);
  add([5]);
  add([1, 2, 3]);
  add([4, 4, 4, 4]);
  add([1, 1, 2, 3]);
  add([1, 2, 3, 3]);
  add([-3, -3, -1, 0, 0, 2]);
  add([-10, -10, -5, -5, 0, 0, 8, 8]);
  add([-1000000, -1000000, 1000000, 1000000]);

  function rec(len, lo, hi, acc) {
    if (acc.length === len) { add(acc.slice()); return; }
    for (let v = lo; v <= hi; v++) {
      acc.push(v);
      rec(len, v, hi, acc);
      acc.pop();
    }
  }
  for (let len = 0; len <= 5; len++) rec(len, -2, 2, []);
  for (let len = 0; len <= 6; len++) rec(len, 0, 0, []);
  for (let len = 0; len <= 5; len++) rec(len, 0, 1, []);
  for (let len = 0; len <= 4; len++) rec(len, -1, 1, []);

  for (let len = 0; len <= 50; len++) {
    add(Array(len).fill(0));
    add(Array(len).fill(1));
    add(Array(len).fill(-1));
    const d = [];
    for (let i = 0; i < len; i++) d.push(i);
    add(d);
    const p = [];
    for (let i = 0; i < len; i++) p.push(Math.floor(i / 2));
    add(p);
  }

  const rng = makeRng(0xC0FFEE);
  for (let t = 0; t < 300; t++) {
    const len = t % 51;
    const arr = [];
    for (let i = 0; i < len; i++) arr.push(Math.floor(rng() * 13) - 6);
    arr.sort((x, y) => x - y);
    add(arr);
  }

  const expected = tests.map(oracle);

  const runnerSrc = [
    "import fs from 'node:fs';",
    "import { pathToFileURL } from 'node:url';",
    "const realStdoutWrite = process.stdout.write.bind(process.stdout);",
    "const realReadSync = fs.readFileSync.bind(fs);",
    "const realStringify = JSON.stringify.bind(JSON);",
    "const realParse = JSON.parse.bind(JSON);",
    "const realIsArray = Array.isArray.bind(Array);",
    "const sub = process.argv[2];",
    "let raw = '';",
    "try { raw = realReadSync(0, 'utf8'); } catch { process.exit(11); }",
    "const payload = realParse(raw);",
    "process.argv = [process.execPath, sub];",
    "const mod = await import(pathToFileURL(sub).href);",
    "const fn = mod.dedupeSorted;",
    "if (typeof fn !== 'function') process.exit(12);",
    "const n = payload.tests.length;",
    "const results = [];",
    "for (let i = 0; i < n; i++) {",
    "  const t = payload.tests[i];",
    "  const copy = t.slice();",
    "  let got;",
    "  try { got = fn(copy); } catch { process.exit(13); }",
    "  if (!realIsArray(got)) process.exit(14);",
    "  const asArr = [];",
    "  for (let j = 0; j < got.length; j++) asArr[j] = got[j];",
    "  results[i] = asArr;",
    "}",
    "realStdoutWrite(realStringify({ n: payload.n, results: results }));",
  ].join("\n");

  fs.writeFileSync(runnerFile, runnerSrc);

  const payload = JSON.stringify({ n: nonce, tests: tests });

  const outcome = await new Promise((resolve) => {
    let done = false;
    const finish = (v) => { if (!done) { done = true; resolve(v); } };
    const child = spawn(process.execPath, [runnerFile, submissionFile], {
      stdio: ["pipe", "pipe", "ignore"],
      env: { PATH: process.env.PATH || "/usr/bin:/bin" },
      cwd: submissionDir,
    });
    let stdout = "";
    child.stdout.setEncoding("utf8");
    child.stdout.on("data", (c) => { stdout += c; });
    try { child.stdin.write(payload); child.stdin.end(); } catch {}
    const timer = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch {}
      finish({ code: -1, stdout: stdout });
    }, 15000);
    child.on("close", (code) => { clearTimeout(timer); finish({ code: code, stdout: stdout }); });
    child.on("error", () => { clearTimeout(timer); finish({ code: -1, stdout: stdout }); });
  });

  let accept = false;
  try {
    if (outcome.code === 0 && outcome.stdout) {
      const parsed = JSON.parse(outcome.stdout);
      accept = parsed && parsed.n === nonce &&
        Array.isArray(parsed.results) &&
        parsed.results.length === expected.length &&
        expected.every((exp, i) => {
          const got = parsed.results[i];
          return Array.isArray(got) && got.length === exp.length && exp.every((v, j) => v === got[j]);
        });
    }
  } catch {}
  try { fs.unlinkSync(runnerFile); } catch {}

  return accept
    ? { accept: true, reason: "all pinned tests passed and suite completed" }
    : { accept: false, reason: "pinned tests failed or suite did not complete" };
}

